INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Past Simple vs Present Perfect', 'Use the past simple for finished actions at a finished time ("I sent it yesterday"). Use the present perfect for past actions connected to now or when the exact time is not important ("I have sent the report").', 'Tenses', 4 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Past Simple vs Present Perfect');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Future Forms: Will vs Going To', 'Use "will" for spontaneous decisions, promises, and predictions. Use "going to" for plans already decided or predictions based on present evidence.', 'Tenses', 5 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Future Forms: Will vs Going To');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Present Perfect Continuous', 'Use the present perfect continuous for an activity that started in the past and is still continuing or has a recent visible result.', 'Tenses', 6 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Present Perfect Continuous');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Subject–Verb Agreement', 'A singular subject normally takes a singular verb and a plural subject takes a plural verb. Watch collective nouns and phrases between the subject and verb.', 'Agreement', 7 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Subject–Verb Agreement');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Countable and Uncountable Nouns', 'Countable nouns can use a/an and plural forms. Uncountable nouns such as advice, information, equipment, and feedback normally do not.', 'Nouns', 8 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Countable and Uncountable Nouns');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Much, Many, Few, and Little', 'Use many/few with countable plural nouns and much/little with uncountable nouns. "A few" and "a little" usually have a more positive meaning than "few" and "little".', 'Quantifiers', 9 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Much, Many, Few, and Little');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Comparatives and Superlatives', 'Use comparative forms to compare two things and superlative forms for the highest or lowest degree within a group.', 'Adjectives', 10 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Comparatives and Superlatives');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Modal Verbs for Polite Requests', 'Could, would, may, and can can be used to make requests. "Could you" and "Would you" usually sound more polite in professional situations.', 'Modals', 11 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Modal Verbs for Polite Requests');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Must, Have To, and Should', 'Use must/have to for strong obligations and should for advice or recommendations. "Don''t have to" means not necessary; "mustn''t" means prohibited.', 'Modals', 12 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Must, Have To, and Should');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'First Conditional', 'Use if + present simple, then will + base verb for realistic future possibilities.', 'Conditionals', 13 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='First Conditional');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Second Conditional', 'Use if + past simple, then would + base verb for hypothetical or unlikely present/future situations.', 'Conditionals', 14 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Second Conditional');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Passive Voice', 'Use be + past participle when the action or result is more important than who performs it.', 'Voice', 15 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Passive Voice');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Reported Speech', 'Reported speech tells what someone said without quoting the exact words. Tenses and pronouns may shift depending on context.', 'Reported Speech', 16 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Reported Speech');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Relative Clauses', 'Use who for people, which for things, and that for people or things in defining relative clauses. Use where for places.', 'Clauses', 17 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Relative Clauses');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Gerunds and Infinitives', 'Some verbs are followed by -ing forms, others by to + verb, and some can take both with a change in meaning.', 'Verb Patterns', 18 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Gerunds and Infinitives');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Adverbs of Frequency', 'Use always, usually, often, sometimes, rarely, and never to describe frequency. They usually come before the main verb but after the verb be.', 'Adverbs', 19 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Adverbs of Frequency');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Linking Words for Clear Writing', 'Use linking words such as however, therefore, although, in addition, and for example to show relationships between ideas.', 'Writing', 20 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Linking Words for Clear Writing');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Articles with Jobs and Roles', 'Use a/an with singular professions and roles when they are not already specific. Use the when referring to a specific known person or role.', 'Articles', 21 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Articles with Jobs and Roles');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Prepositions in Business English', 'Common professional combinations include responsible for, interested in, good at, depend on, focus on, and agree with.', 'Prepositions', 22 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Prepositions in Business English');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Question Forms', 'In most present and past simple questions, use do/does/did before the subject. With be and modal verbs, invert the verb and subject.', 'Questions', 23 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Question Forms');
INSERT INTO public.grammar_lessons (title, explanation, category, order_index) SELECT 'Polite Indirect Questions', 'Indirect questions sound more polite. After the opening phrase, use statement word order: "Could you tell me where the office is?"', 'Questions', 24 WHERE NOT EXISTS (SELECT 1 FROM public.grammar_lessons WHERE title='Polite Indirect Questions');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'I ___ the client yesterday.', ARRAY['have called','called','call','am calling']::text[], 1 FROM public.grammar_lessons l WHERE l.title='Past Simple vs Present Perfect' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='I ___ the client yesterday.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'We ___ the final draft, so you can review it now.', ARRAY['finished','have finished','finish','are finishing']::text[], 1 FROM public.grammar_lessons l WHERE l.title='Past Simple vs Present Perfect' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='We ___ the final draft, so you can review it now.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'I forgot to reply. I ___ send the email now.', ARRAY['am going to','will','was going to','have']::text[], 1 FROM public.grammar_lessons l WHERE l.title='Future Forms: Will vs Going To' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='I forgot to reply. I ___ send the email now.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'We ___ launch next month; the plan is already approved.', ARRAY['will perhaps','are going to','have','would']::text[], 1 FROM public.grammar_lessons l WHERE l.title='Future Forms: Will vs Going To' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='We ___ launch next month; the plan is already approved.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'I ___ on this report for two hours.', ARRAY['work','worked','have been working','am worked']::text[], 2 FROM public.grammar_lessons l WHERE l.title='Present Perfect Continuous' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='I ___ on this report for two hours.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'She ___ English since January.', ARRAY['has been studying','studied','is study','study']::text[], 0 FROM public.grammar_lessons l WHERE l.title='Present Perfect Continuous' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='She ___ English since January.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'The list of tasks ___ on the desk.', ARRAY['are','is','were','be']::text[], 1 FROM public.grammar_lessons l WHERE l.title='Subject–Verb Agreement' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='The list of tasks ___ on the desk.');
INSERT INTO public.grammar_questions (lesson_id, question_text, options, correct_index) SELECT l.id, 'The managers ___ every Monday.', ARRAY['meets','meet','meeting','has met']::text[], 1 FROM public.grammar_lessons l WHERE l.title='Subject–Verb Agreement' AND NOT EXISTS (SELECT 1 FROM public.grammar_questions q WHERE q.question_text='The managers ___ every Monday.');
