INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Project Status Update', 'Business', 'Good afternoon everyone. The design phase is complete and development is on schedule. We are waiting for final approval on the payment flow, so that remains our only blocker. If approval arrives by Wednesday, we still expect to launch next Monday.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Project Status Update');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Client Deadline Negotiation', 'Business', 'Thanks for sharing the revised deadline. Delivering by Friday would be difficult without reducing the testing period. We can either deliver the core features on Friday and the remaining items on Tuesday, or move the complete delivery to Tuesday. Which option works better for you?' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Client Deadline Negotiation');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Performance Feedback', 'Business', 'I appreciate the quality of your work and the way you support the team. One area to improve is communicating risks earlier. If you flag delays as soon as you notice them, we can help remove blockers before they affect the deadline.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Performance Feedback');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Networking Introduction', 'Business', 'Hi, I’m Riya. I work in operations for a logistics company in Pune. I’m here because I’m interested in how small teams are using automation to improve customer service. What kind of work are you involved in?' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Networking Introduction');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Airport Change of Gate', 'Travel', 'Attention passengers travelling to Bengaluru on flight 6E 412. Your departure gate has changed from gate 18 to gate 24. Boarding will begin at 6:10 PM, twenty minutes later than originally scheduled. We apologize for the inconvenience.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Airport Change of Gate');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Hotel Check-in', 'Travel', 'Welcome to the Riverside Hotel. Your room is on the seventh floor and breakfast is served from 7 to 10 AM in the restaurant beside the lobby. Wi-Fi is included. Checkout is at 11 AM, but we can store your luggage afterward if needed.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Hotel Check-in');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Doctor Appointment', 'Everyday', 'Your appointment with Dr. Mehta is confirmed for Thursday at 4:30 PM. Please arrive ten minutes early and bring any recent test reports. If you need to cancel, call us at least four hours before the appointment.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Doctor Appointment');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Restaurant Order', 'Everyday', 'I’d like the grilled paneer wrap, please, but without onions. Could I have the sauce on the side? And instead of fries, I’ll take the salad. For the drink, just a bottle of water.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Restaurant Order');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Weekend Plan Change', 'Casual', 'I was going to meet Arjun for lunch on Saturday, but he has to work. We moved it to Sunday evening instead. I’ll probably use Saturday to finish some errands and then relax at home.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Weekend Plan Change');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Job Interview Scheduling', 'Interview', 'Thank you for applying for the analyst role. We would like to invite you to a second interview with the team lead. We have openings on Tuesday at 11 AM and Wednesday at 3 PM. Please reply with your preferred time by Monday evening.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Job Interview Scheduling');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Interview Candidate Answer', 'Interview', 'In my previous role, our monthly report took almost two days to prepare. I mapped the process, removed duplicate steps, and created a simple automated template. That reduced preparation time to about three hours and also lowered data-entry errors.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Interview Candidate Answer');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'University Assignment Reminder', 'Academic', 'This is a reminder that your research summary is due next Friday at 5 PM. It should be between 800 and 1,000 words and include at least five academic sources. Submit the document through the student portal; email submissions will not be accepted.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='University Assignment Reminder');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Customer Support Call', 'Business', 'I can see that your payment was successful, but the order is still showing as pending. I’m going to refresh the order status from our side. If it does not update within ten minutes, I’ll create a priority ticket and email you the reference number.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Customer Support Call');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Team Stand-up', 'Business', 'Yesterday I completed the dashboard filters and fixed the export bug. Today I’m working on the mobile layout. I’m blocked by one thing: I need the final icon set from design before I can finish the header.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Team Stand-up');
INSERT INTO public.listening_clips (title, category, transcript) SELECT 'Delivery Update', 'Everyday', 'Your package has left the local sorting centre and is expected to arrive tomorrow between 2 and 6 PM. A signature will be required. If no one is available, the courier will attempt delivery again the following business day.' WHERE NOT EXISTS (SELECT 1 FROM public.listening_clips WHERE title='Delivery Update');
