INSERT INTO public.listening_questions (clip_id, question_text, options, correct_index) SELECT c.id, 'What was fixed yesterday?', ARRAY['The login issue','The export bug','The payment gateway','The search bar']::text[], 1 FROM public.listening_clips c WHERE c.title='Team Stand-up' AND NOT EXISTS (SELECT 1 FROM public.listening_questions q WHERE q.question_text='What was fixed yesterday?');
INSERT INTO public.listening_questions (clip_id, question_text, options, correct_index) SELECT c.id, 'What is needed from design?', ARRAY['Final icon set','A new logo name','Budget approval','Customer data']::text[], 0 FROM public.listening_clips c WHERE c.title='Team Stand-up' AND NOT EXISTS (SELECT 1 FROM public.listening_questions q WHERE q.question_text='What is needed from design?');
INSERT INTO public.listening_questions (clip_id, question_text, options, correct_index) SELECT c.id, 'When is the package expected?', ARRAY['Today morning','Tomorrow between 2 and 6 PM','Next week','Tonight']::text[], 1 FROM public.listening_clips c WHERE c.title='Delivery Update' AND NOT EXISTS (SELECT 1 FROM public.listening_questions q WHERE q.question_text='When is the package expected?');
INSERT INTO public.listening_questions (clip_id, question_text, options, correct_index) SELECT c.id, 'What is required at delivery?', ARRAY['A photo ID only','Cash payment','A signature','A printed invoice']::text[], 2 FROM public.listening_clips c WHERE c.title='Delivery Update' AND NOT EXISTS (SELECT 1 FROM public.listening_questions q WHERE q.question_text='What is required at delivery?');
INSERT INTO public.writing_prompts (title, category, instructions) SELECT 'Follow Up After No Reply', 'Email', 'Write a polite follow-up email after you have not received a response for five business days. Keep it concise and professional.' WHERE NOT EXISTS (SELECT 1 FROM public.writing_prompts WHERE title='Follow Up After No Reply');
